175	  }
176	  if (name === 'add' || name === 'replace' || name === 'test') {
177	    if (!Object.hasOwn(op, 'value')) return 'missing value';
178	    parsed.value = op.value;
179	  }
180	  if (name === 'remove' && path.length === 0) return 'cannot remove root';
181	  if (name === 'move' && isProperPrefix(parsed.from, path)) return 'cannot move into own child';
