185	function applyOperation(doc, { op, path, from, value }, fail) {
186	  switch (op) {
187	    case 'add':
188	      return addAt(doc, path, clone(value), fail);
189	    case 'remove':
190	      removeAt(doc, path, 'path not found', fail);
191	      return doc;
192	    case 'replace': {
193	      if (path.length === 0) return clone(value);
194	      const { parent, key } = locate(doc, path, 'path not found', fail);
195	      if (Array.isArray(parent)) parent[Number(key)] = clone(value);
196	      else setMember(parent, key, clone(value));
197	      return doc;
198	    }
199	    case 'move': {
200	      if (sameTokens(from, path)) {
201	        follow(doc, from, 'from not found', fail);
202	        return doc;
203	      }
204	      // The form rules guarantee `from` is not "" here, so it has a parent.
205	      const moved = removeAt(doc, from, 'from not found', fail);
206	      return addAt(doc, path, moved, fail);
207	    }
208	    case 'copy':
209	      return addAt(doc, path, clone(follow(doc, from, 'from not found', fail)), fail);
210	    case 'test':
211	      if (!deepEqual(follow(doc, path, 'path not found', fail), value)) fail('test failed');
