60	async function readStdinBytes() {
61	  const chunks = [];
62	  let total = 0;
63	  try {
64	    for await (const chunk of process.stdin) {
65	      chunks.push(chunk);
66	      total += chunk.length;
67	      if (total > MAX_BYTES) return 'too large';
68	    }
69	  } catch {
70	    return 'cannot read';
71	  }
72	  return Buffer.concat(chunks, total);
