87	async function loadJson(arg) {
88	  const name = arg === '-' ? 'stdin' : arg;
89	  const bytes = arg === '-' ? await readStdinBytes() : readFileBytes(arg);
90	  if (typeof bytes === 'string') throw new CliError(`Error: ${name}: ${bytes}`, 1);
91	  const hasBom = bytes.length >= 3 && bytes[0] === 0xef && bytes[1] === 0xbb && bytes[2] === 0xbf;
92	  let text;
93	  try {
94	    text = new TextDecoder('utf-8', { fatal: true, ignoreBOM: true }).decode(hasBom ? bytes.subarray(3) : bytes);
95	  } catch {
96	    throw new CliError(`Error: ${name}: invalid UTF-8`, 3);
97	  }
98	  let value;
99	  try {
100	    value = JSON.parse(text);
101	  } catch {
102	    throw new CliError(`Error: ${name}: invalid JSON`, 3);
103	  }
104	  if (exceedsDepth(value, MAX_DEPTH)) throw new CliError(`Error: ${name}: too deep`, 3);
